import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"公司对冲的理由","description":"","frontmatter":{"title":"公司对冲的理由","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/corporate-hedging-rationale.md","filePath":"econ/corporate-hedging-rationale.md","lastUpdated":1789023840000}'),h={name:"econ/corporate-hedging-rationale.md"};function c(A,a,m,S,B,_){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="公司对冲的理由" tabindex="-1">公司对冲的理由 <a class="header-anchor" href="#公司对冲的理由" aria-label="Permalink to &quot;公司对冲的理由&quot;">​</a></h1><div class="epigraph"><p>在 MM 世界里股东自己能对冲，企业代劳没有价值；有税、破产成本、融资约束与经理风险厌恶时，企业风险管理可以改变真实投资。</p><footer>—— Smith and Stulz, The Determinants of Firms&#39; Hedging Policies, Journal of Financial and Quantitative Analysis 1985；Froot, Scharfstein and Stein, Journal of Finance 1993</footer></div><p><a href="/econ/insider-trading-theory">上一课</a>把经理的信息与交易写完。对冲是经理与企业改变风险暴露的合同。本课缺口是：为何公司要做衍生品与保险，而不是留给股东。不重写内部人租金，不把衍生品定价或限价簿写成主体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/modigliani-miller">MM 1958</a>：切片与自制杠杆无关，自制对冲同样。Smith–Stulz：凸的税函数、破产成本、经理凹效用，使企业层面降波动有价值。Froot–Scharfstein–Stein（FSS）：外部融资贵时，内部现金流波动导致投资波动；对冲使好项目不因汇率或利率冲击而停摆——把优序与实物期权接到风险管理。缺口是列出许可证，禁止「降低 beta 就能提高价值」——可分散风险不进 CAPM 门槛，对冲可分散风险不改变 \\(r_U\\)，只改变融资摩擦与税。</p><p><span class="marginnote">FSS：对冲的是与投资机会相关的现金，而不是把所有波动对冲到零。投资机会与现金正相关时，对冲需求下降——自然对冲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>许可证清单：（1）税：累进或税损不对称，平滑应税所得提高税后现金；（2）困境：降低 \\(V\\) 碰到 \\(V_B\\) 的概率，税盾更安全，债务容量上升——动态权衡带变窄或中心上移；（3）融资约束：保证 capex 不中断；（4）经理：薪酬与人力资本不可分散，企业代为对冲可能降低风险补偿，或让经理敢投正 NPV（否则他们用高门槛自我保险）；（5）比较劣势：股东无法复制的保险（商品、特定税收）。</p><p>不是许可证：降低可分散风险以「降低 WACC」——除非通过（2）（3）改变真实杠杆或投资。资本预算：对冲成本进 FCFF 或 APV，不要把 WACC 减去一个「对冲折扣」。</p>',9)),(e(),s(p,null,{default:r(()=>[E(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM%5B%22MM%3A%20%E8%82%A1%E4%B8%9C%E8%87%AA%E5%88%B6%22%5D%20--%3E%20NO%5B%22%E6%97%A0%E6%91%A9%E6%93%A6%E5%88%99%E6%97%A0%E4%BB%B7%E5%80%BC%22%5D%0A%20%20TAX%5B%22%E7%A8%8E%E5%87%B8%E6%80%A7%22%5D%20--%3E%20YES%5B%22%E4%BC%81%E4%B8%9A%E4%BB%A3%E5%8A%B3%E6%9C%89%E4%BB%B7%E5%80%BC%22%5D%0A%20%20DIST%5B%22%E7%A0%B4%E4%BA%A7%20%2F%20%E7%A7%AF%E5%8E%8B%22%5D%20--%3E%20YES%0A%20%20FSS%5B%22%E5%A4%96%E9%83%A8%E8%9E%8D%E8%B5%84%E8%B4%B5%22%5D%20--%3E%20INV%5B%22%E4%BF%9D%E6%8A%A4%E6%8A%95%E8%B5%84%22%5D%0A%20%20MGR%5B%22%E7%BB%8F%E7%90%86%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%22%5D%20--%3E%20YES%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与国家风险：汇率对冲是 \\(\\lambda\\) 的操作，不能替代征收情景。与空壳：债权人要求对冲作为契约，是条款课的延续。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是摩擦使波动进入真实支出。税与破产是非线性；融资优序使内部现金的影子价格高。对冲把状态之间的现金挪到投资影子价格高的状态。这与家庭保险同构，对象是企业投资，不是消费欧拉的再推导。</p><p>代理阴暗面：经理对冲自己的职业风险，股东要的暴露被对掉；或用衍生品做投机、隐藏杠杆——对冲账户变成择时与赌博。董事会监督与披露是治理，不是定价模型。</p><h3 id="不要用对冲替代国家风险溢价的情景" tabindex="-1">不要用对冲替代国家风险溢价的情景 <a class="header-anchor" href="#不要用对冲替代国家风险溢价的情景" aria-label="Permalink to &quot;不要用对冲替代国家风险溢价的情景&quot;">​</a></h3><p>把 CRP 加进 WACC 又把现金流当成已对冲，口径混乱。能对冲的进成本，不能对冲的进情景或 \\(\\lambda\\)，与第一单元最后一课一致。</p><p><span class="marginnote">Smith–Stulz <em>JFQA</em> 1985。Froot, Scharfstein and Stein, <em>JF</em> 1993。Brealey–Myers 把「股东自己能做的」排除出公司对冲清单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成期权希腊字母。下一课现金持有：对冲的替代是囤现金与信贷额度，同一 FSS 逻辑。ESG 会把目标函数从股东价值扩开，对冲清单跟着变。</p><p>后课默认：公司对冲只在税、困境、融资约束或经理激励下创造价值；不降低可分散风险的 \\(r_U\\)。投机性衍生品是治理问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MM 下企业对冲无价值；税、破产、优序融资约束给出许可证。</li><li>FSS：对冲保护外部融资贵时的投资，不是把 beta 对到零。</li><li>成本进现金或 APV；禁止用「对冲降低 WACC」当接受规则。</li><li>出处：Smith and Stulz, <em>JFQA</em> 1985；Froot, Scharfstein and Stein, <em>JF</em> 1993。</li></ul>',12))])}const C=o(h,[["render",c]]);export{f as __pageData,C as default};
